CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
    INSERT INTO public.profiles (id, brand, tier)
    VALUES (
        NEW.id,
        COALESCE(NEW.raw_user_meta_data->>'brand', 'flowen'),
        COALESCE(
            (NEW.raw_user_meta_data->>'tier')::subscription_tier,
            'standard'
        )
    )
    ON CONFLICT (id) DO NOTHING;
    RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION notify_slp_new_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
declare
  recipient_role text;
  sender_name    text;
begin
  select role into recipient_role from profiles where id = new.to_user_id;
  if recipient_role in ('clinician', 'slp') then
    select coalesce(display_name, email) into sender_name from profiles where id = new.from_user_id;
    insert into slp_notifications (slp_user_id, type, title, body, link, priority)
    values (
      new.to_user_id,
      'new_message',
      'New message from ' || coalesce(sender_name, 'a patient'),
      left(new.content, 140),
      '/dashboard/messages',
      'normal'
    );
  end if;
  return new;
end;
$$

CREATE OR REPLACE FUNCTION notify_slp_session_completed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
declare
  patient_name text;
  assignment   record;
begin
  select coalesce(display_name, email) into patient_name from profiles where id = new.user_id;
  for assignment in
    select slp_user_id from slp_assignments where patient_user_id = new.user_id
  loop
    insert into slp_notifications (slp_user_id, type, title, body, link, priority)
    values (
      assignment.slp_user_id,
      'session_completed',
      coalesce(patient_name, 'A patient') || ' completed a practice session',
      'Stage ' || new.stage_id || ' - ' || round((new.duration_seconds / 60.0)::numeric, 1) || ' min - '
        || coalesce(new.total_blocks_detected, 0) || ' blocks detected',
      '/dashboard/clinician',
      'normal'
    );
  end loop;
  return new;
end;
$$

DO $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'consent_records_identity_check'
  ) then
    alter table public.consent_records
      add constraint consent_records_identity_check
      check (anonymous_id is not null or user_id is not null);
  end if;
end $$
